Efficient Approach: The idea is to solve the problem using Prefix Sum and Hashing. Below are the steps:

Calculate the Prefix Sum of the array and store it in HashMap.Iterate through the array and for every ith index, where i ranges from [0, N - 1], check if the element at the ith index is negative or not. If so, then arr[i] is the required subarray.Otherwise, find an index starting from i + 1, where the prefix sum is smaller than the prefix sum up to i.If any such index is found in the above step, then the subarray from indices {i, index} gives the first negative subarray.If no such subarray is found, print "-1". Otherwise, print the obtained subarray.Below is the implementation of the above approach: 



            C++

    // CPP program for the above approach
#include <bits/stdc++.h>
using namespace std;

// Function to check if a sum less
// than pre_sum is present
int b_search(int pre_sum,
             map<int, vector<int> >& m,
             int index)
{
    // Returns an iterator either equal
    // to given key or next greater
    auto it = m.lower_bound(pre_sum);

    if (it == m.begin())
        return -1;

    // Decrement the iterator
    it--;

    // Check if the sum found at
    // a greater index
    auto it1
        = lower_bound(it->second.begin(),
                      it->second.end(),
                      index);

    if (*it1 > index)
        return *it1;

    return -1;
}

// Function to return the index
// of first negative subarray sum
vector<int> findSubarray(int arr[], int n)
{
    // Stores the prefix sum- index
    // mappings
    map<int, vector<int> > m;

    int sum = 0;

    // Stores the prefix sum of
    // the original array
    int prefix_sum[n];

    for (int i = 0; i < n; i++) {
        sum += arr[i];

        // Check if we get sum negative
        // starting from first element
        if (sum < 0)
            return { 0, i };

        prefix_sum[i] = sum;
        m[sum].push_back(i);
    }

    // Iterate through array find
    // the sum which is just less
    // then the previous prefix sum
    for (int i = 1; i < n; i++) {

        // Check if the starting element
        // is itself negative
        if (arr[i] < 0)

            // arr[i] becomes the required
            // subarray
            return { i, i };

        else {
            int pre_sum = prefix_sum[i - 1];

            // Find the index which forms
            // negative sum subarray
            // from i-th index
            int index = b_search(pre_sum,
                                 m, i);

            // If a subarray is found
            // starting from i-th index
            if (index != -1)
                return { i, index };
        }
    }

    // Return -1 if no such
    // subarray is present
    return { -1 };
}

